import { atom, read, update } from 'claude-code'
import type { BoxProps, ElementConstructor, EngineInterface, Register, Timer } from 'claude-code'

import type { PrintLevel } from '../types'
import { ACROSS, BLOCK_ART, ORANGE, PALETTE, SETTLED_TICKS, TICK_MS, cadence, chart, compact, frame, grouped, isAsleep, isIntro, meme, sparkline, strip } from './art'
import type { Gaze, Scene } from './art'
import { caretAt } from './caret'

const printed = atom({ plugin: 'token-printer', key: 'printed' } as const, 0)
const runs = atom({ plugin: 'token-printer', key: 'runs' } as const, [])
const isUltra = atom({ plugin: 'token-printer', key: 'isUltra' } as const, false)
const isPrinting = atom({ plugin: 'token-printer', key: 'isPrinting' } as const, false)
const isBandHidden = atom({ plugin: 'token-printer', key: 'isBandHidden' } as const, false)
// The band alone reads it: a write redraws the band and nothing else.
const redraw = atom({ plugin: 'token-printer', key: 'redraw' } as const, 0)
const redrawRef = { plugin: 'token-printer', key: 'redraw' } as const

const RESERVE = 'token-reserve'

/** How hard the printer runs for what the turn is doing. */
const LEVEL = { requesting: 0, 'tool-input': 1, 'tool-use': 1, thinking: 2, responding: 3 } as const

const WORD = [
  'Token printer warming up',
  'Token printer go brr',
  'Token printer go brrrr',
  'Token printer go BRRRRR',
] as const

const MILESTONES = [
  [10_000, 'The printer is warmed up.'],
  [50_000, 'brrrrrrrrrrrrrrrrrrrrrr'],
  [100_000, 'The Fed has entered the chat.'],
  [250_000, 'Number go up.'],
  [500_000, 'Quantitative easing: ∞'],
  [1_000_000, 'Hyperinflation achieved.'],
] as const

const pick = (options: readonly [string, ...string[]]) =>
  options[Math.floor(Math.random() * options.length)] ?? options[0]

/** What the session has cost so far, in dollars; 0 where the host keeps no ledger. */
const spent = async ($: EngineInterface) => (await $.session.usage()).cost?.usd ?? 0

const dollars = (usd: number) => (usd >= 0.01 ? `$${usd.toFixed(2)}` : '')

/**
 * The prompt box's text width, from the band's columns. Measured on the
 * desktop: a band of 95 columns is 768px wide and one of 69 is 565px; the box
 * under it is as wide, and its padding and send button take 46px of that.
 */
const PX_PER_COLUMN = (768 - 565) / (95 - 69)
const BAND_PX_AT_ZERO = 768 - 95 * PX_PER_COLUMN
const TEXT_INSET_PX = 46


/** A row of a frame as runs of one letter: [letter, first column, length]. */
function runsOf(row: string): [string, number, number][] {
  const out: [string, number, number][] = []
  for (let x = 0; x < row.length; x += 1) {
    const letter = row.charAt(x)
    const last = out[out.length - 1]
    if (last !== undefined && last[0] === letter) last[2] += 1
    else out.push([letter, x, 1])
  }
  return out
}

/** A frame as boxes: each line a row of runs, each pixel 1% wide and 5% tall. */
function pixels(Box: ElementConstructor<BoxProps>, rows: readonly string[]) {
  return (
    <Box flexDirection="column" width="100%" height="100%">
      {rows.map((row, y) => (
        <Box key={`r${y}`} flexDirection="row" width="100%" height="5%">
          {runsOf(row).filter(([letter], i, all) => letter !== '.' || i < all.length - 1).map(([letter, from, length]) => {
            const color = PALETTE[letter]
            return color === undefined
              ? <Box key={`c${from}`} width={`${length}%`} height="100%" />
              : <Box key={`c${from}`} width={`${length}%`} height="100%" backgroundColor={color} />
          })}
        </Box>
      ))}
    </Box>
  )
}

export const register: Register = on => {
  // What the spinner last said the turn is doing: the band and the pane print at it.
  let level: PrintLevel = 0
  // Where the running reply started from, for its receipt.
  let start = { printed: 0, usd: 0 }
  // Whether the main loop's last request ran at Max effort, once one has.
  let isMaxEffort: boolean | undefined
  // The prompt box holds a draft (Clawd is up and watching it), and whether a
  // print run ended since the last draft (the printer still steams).
  let hasDraft = false
  let hasPrinted = false
  // Where the caret is, as Clawd's gaze, and the band's width in columns.
  let gaze: Gaze = { across: 0, isLower: false }
  let columns = 95
  // Our own copy of the draft and caret, to measure again when the box resizes.
  let draft = ''
  let caret = 0
  // The band's clock: ticks so far, the scene drawn last and the tick it began
  // at, whether the band shows, and a redraw asked for by a render hook (which
  // cannot write state itself). `redraws` is the value written to `redraw`.
  let clock: Timer | undefined
  let tick = 0
  let scene: Scene = 'drowsy'
  let sceneStart = 0
  let isBandShown = false
  let isRedrawDue = false
  let redraws = 0

  /** Notes whether the box holds a draft; true when that flipped, so the band redraws. */
  const noteDraft = (isDraft: boolean) => {
    if (isDraft === hasDraft) {
      return false
    }

    hasDraft = isDraft
    hasPrinted &&= !hasDraft
    return true
  }

  /** Notes where the caret is; true when Clawd should look somewhere else. */
  const noteCaret = (text: string, cursor: number) => {
    const width = BAND_PX_AT_ZERO + columns * PX_PER_COLUMN - TEXT_INSET_PX
    const caret = caretAt(text, cursor, width)
    const next = { across: Math.min(ACROSS - 1, Math.floor((caret.x / width) * ACROSS)), isLower: caret.line > 0 }

    if (next.across === gaze.across && next.isLower === gaze.isLower) {
      return false
    }

    gaze = next
    return true
  }

  on('session.start', async ($, e, next) => {
    // The band's clock: redraw it whenever its scene has moved on a frame.
    clock ??= $.clock.every(TICK_MS, () => {
      tick += 1
      const t = tick - sceneStart

      if (isBandShown && (isRedrawDue || t % cadence(scene, t) === 0)) {
        isRedrawDue = false
        redraws += 1
        void $.state.set(redrawRef, redraws)
      }
    })

    await $.command.register({
      name: 'brrr',
      description: 'Token printer go brrr: post the meme with this session’s numbers',
      argumentHint: '[what to beg the printer]',
    })
    await $.command.register({
      name: RESERVE,
      description: 'Open the Token Reserve: what the printer printed, reply by reply',
    })

    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    // The draft was just sent: the box is empty again.
    hasDraft = false
    draft = ''
    caret = 0
    start = { printed: await read($, printed), usd: await spent($) }
    await update($, isPrinting, () => true)

    return next(e)
  })

  // Each request says the effort it runs at: Max is Clawd's ultra mode (shades).
  // The picker raises no event of its own, so a change shows from the next turn.
  on('turn.step', async function* ($, e, next) {
    const isMax = e.effort === 'max'

    if (e.agentId === undefined && isMax !== isMaxEffort) {
      isMaxEffort = isMax
      void update($, isUltra, () => isMax)
    }

    return yield* next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const fresh = e.usage?.output_tokens ?? 0
    const total = fresh > 0 ? await update($, printed, n => n + fresh) : await read($, printed)

    if (fresh > 0) {
      const hit = MILESTONES.filter(([at]) => total - fresh < at && at <= total).pop()

      if (hit !== undefined) {
        $.ui.toast(`🖨️ ${compact(hit[0])} tokens printed. ${hit[1]}`)
      }

      await $.store.set('lifetime', Number((await $.store.get('lifetime')) ?? 0) + fresh)
    }

    // A subagent's answer is its parent's to read: no receipt on it.
    if (e.agentId !== undefined) {
      return next(e)
    }

    await update($, isPrinting, () => false)
    const done = await next(e)
    const run = total - start.printed

    if (run <= 0) {
      return done
    }

    await update($, runs, list => [...list, run].slice(-30))
    const cost = dollars((await spent($)) - start.usd)
    const shades = (await read($, isUltra)) ? ' 😎' : ''

    return { ...done, text: `🖨️ +${grouped(run)} tokens printed${cost ? ` (+${cost})` : ''} · brrr${shades}` }
  })

  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    const now: PrintLevel = LEVEL[e.props.mode]

    if (now !== level) {
      level = now
      isRedrawDue = true
    }

    if (e.surface === 'terminal') {
      const shades = (await read($, isUltra)) ? ' 😎' : ''

      return next({ ...e, props: { ...e.props, word: `${WORD[now]}${shades}` } })
    }

    // The desktop's row stays the engine's: the band above the prompt draws the printer.
    return next(e)
  })

  // Two places say the prompt box holds a draft: each edit of it, and the hint
  // line under it. Either one wakes Clawd.
  on('prompt.edit', async ($, e, next) => {
    const box = await next(e)

    if (e.text === '' && draft !== '') {
      // An edit that comes without the draft (seen once on the desktop): keep
      // ours, as typing at its end; a Backspace takes the last character off.
      if (e.inputText !== '') draft += e.inputText
      else if (e.key?.key === 'backspace') draft = draft.slice(0, -1)
      caret = draft.length
    } else {
      draft = box.text
      caret = box.cursor
    }

    const hasFlipped = noteDraft(draft !== '')
    const hasMoved = noteCaret(draft, caret)

    // Boxes change in place, so the band redraws on the keystroke itself.
    if (hasFlipped || (hasDraft && hasMoved)) {
      redraws += 1
      void $.state.set(redrawRef, redraws)
    }

    return box
  })

  on('ui.render', { component: 'PromptHint' }, ($, e, next) => {
    if (noteDraft(e.props.isDraft)) {
      isRedrawDue = true
    }

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isBandHidden))) {
      isBandShown = false
      return next(e)
    }

    const [total, list, hasShades, usd] = await Promise.all([read($, printed), read($, runs), read($, isUltra), spent($)])
    const last = list.at(-1)
    hasPrinted ||= e.props.isWorking

    // A resized band is a resized prompt box: the draft wraps anew, so look again.
    const width = Math.max(20, e.props.bodyColumns)
    if (width !== columns) {
      columns = width
      noteCaret(draft, caret)
    }
    const upcoming: Scene = e.props.isWorking ? level : hasDraft ? 'ready' : hasPrinted ? 'idle' : 'drowsy'

    // A new scene starts its animation over; a new print level carries on. A
    // draft startles Clawd only out of sleep: awake, he just turns to watch.
    if ((typeof upcoming === 'number') !== (typeof scene === 'number') || (typeof upcoming !== 'number' && upcoming !== scene)) {
      const wasAsleep = isAsleep(scene, tick - sceneStart)
      sceneStart = upcoming === 'ready' && !wasAsleep ? tick - SETTLED_TICKS : tick
    }

    scene = upcoming
    isBandShown = true
    const t = tick - sceneStart
    const caption = scene === 'ready'
      ? isIntro(t) ? 'Ooh, a prompt!' : 'Printer ready 👀'
      : typeof scene === 'number'
        ? `${WORD[scene]}${hasShades ? ' 😎' : ''}`
        : `Printer idle${last === undefined ? '' : ` · last run +${grouped(last)}`}`
    const ledger = [`${grouped(total)} printed`, dollars(usd)].filter(Boolean).join(' · ')
    const hide = async () => {
      await update($, isBandHidden, () => true)
      $.ui.toast('Printer band hidden. /token-reserve brings it back.')
    }

    // Reading `redraw` is what lets the clock redraw the band, and the band alone.
    await read($, redraw)

    if (e.surface === 'terminal') {
      const { Box, Button, Text } = $.ui.resolve(e)

      return (
        <Box flexDirection="row" gap={1}>
          <Text color={ORANGE}>✻ {caption}</Text>
          <Text dimColor>{ledger}</Text>
          <Button key="hide" label="hide" plain dimColor onPress={hide} />
        </Box>
      )
    }

    const { Box, Text } = $.ui.resolve(e)

    // Clawd and his printer are boxes, 40 columns by 3 rows (3px pixels on the
    // desktop), with the caption pinned over the band's right. No Hide button:
    // here the desktop draws it as a pill in the middle; /token-reserve hides.
    return (
      <Box flexDirection="row" height={3}>
        <Box width={40} height={3}>{pixels(Box, frame({ scene, t, hasShades, gaze }))}</Box>
        <Box position="absolute" top={1} right={3} flexDirection="column">
          <Text color={ORANGE} bold>{caption}</Text>
          <Text dimColor>{ledger}</Text>
        </Box>
      </Box>
    )
  })

  on('command.run', { command: RESERVE }, async $ => {
    await $.ui.open({ id: RESERVE, title: 'Token Reserve' })

    return { text: 'Token Reserve opened.' }
  })

  on('ui.render', { component: 'Pane', requestId: RESERVE }, async ($, e) => {
    const [total, list, hasShades, working, hidden, usd, lifetime] = await Promise.all([
      read($, printed), read($, runs), read($, isUltra), read($, isPrinting), read($, isBandHidden), spent($), $.store.get('lifetime'),
    ])
    const lines = [
      [`${grouped(total)} tokens printed this session`, dollars(usd)].filter(Boolean).join(' · '),
      `${list.length} ${list.length === 1 ? 'reply' : 'replies'} · biggest run ${grouped(list.length === 0 ? 0 : Math.max(...list))}`,
      `${grouped(Number(lifetime ?? 0))} tokens printed all-time`,
    ]
    const toggle = () => update($, isBandHidden, isHidden => !isHidden)
    const label = hidden ? 'Show band' : 'Hide band'

    if (e.surface === 'terminal') {
      const { Box, Button, Text } = $.ui.resolve(e)

      return (
        <Box flexDirection="column">
          {BLOCK_ART.map(row => (
            <Box flexDirection="row">
              {row.map(([text, color]) => <Text color={color}>{text}</Text>)}
            </Box>
          ))}
          {lines.map(line => <Text>{line}</Text>)}
          {list.length > 0 && <Text color={ORANGE}>{sparkline(list)}</Text>}
          <Button key="band" label={label} onPress={toggle} />
        </Box>
      )
    }

    const { Box, Button, Svg, Text } = $.ui.resolve(e)

    return (
      <Box flexDirection="column" gap={1}>
        <Svg {...strip(working ? level : 'idle', hasShades, 2)} alt="Clawd at the token printer" isInteractive />
        {lines.map(line => <Text>{line}</Text>)}
        <Text bold>Tokens per reply</Text>
        {list.length > 0
          ? <Svg {...chart(list)} alt={`Tokens per reply, oldest first: ${list.map(grouped).join(', ')}`} isInteractive />
          : <Text dimColor>No replies printed yet.</Text>}
        <Box flexDirection="row">
          <Button key="band" label={label} onPress={toggle} />
        </Box>
      </Box>
    )
  })

  on('command.run', { command: 'brrr' }, async ($, e) => {
    const [total, usage, hasShades] = await Promise.all([read($, printed), $.session.usage(), read($, isUltra)])
    const usd = usage.cost?.usd ?? 0
    const full = usage.context.percent
    const pleas: [string, ...string[]] = [
      'STOP! I asked for a one-line fix!',
      "STOP! You can't just print tokens forever!",
    ]

    if (total > 0) pleas.push(`STOP! You can't just print ${grouped(total)} tokens to fix a typo!`)
    if (usd >= 0.01) pleas.push(`STOP! This session already cost $${usd.toFixed(2)}!`)
    if (full !== undefined && full >= 25) pleas.push(`STOP! The context window is ${Math.round(full)}% full!`)

    const top = e.args.replace(/\s+/g, ' ').trim() || pick(pleas)
    const bottom = `haha token printer go brrrr${hasShades ? ' 😎' : ''}`
    const stats = [`${grouped(total)} tokens printed`, usd >= 0.01 ? `${dollars(usd)} this session` : ''].filter(Boolean).join(' · ')

    return { text: [top, bottom, stats].join('\n') }
  })

  on('ui.render', { component: 'CommandOutput', props: { command: 'brrr' } }, async ($, e, next) => {
    if (e.props.isErrored) {
      return next(e)
    }

    const [top = '', bottom = '', stats = ''] = e.props.text.split('\n')

    if (e.surface === 'terminal') {
      const { Box, Text } = $.ui.resolve(e)

      return (
        <Box flexDirection="column">
          <Text bold>{top}</Text>
          {BLOCK_ART.map(row => (
            <Box flexDirection="row">
              {row.map(([text, color]) => <Text color={color}>{text}</Text>)}
            </Box>
          ))}
          <Text bold color={ORANGE}>{bottom}</Text>
          <Text dimColor>{stats}</Text>
        </Box>
      )
    }

    const { Svg } = $.ui.resolve(e)

    return <Svg {...meme(top, bottom, stats, bottom.includes('😎'))} alt={`${top} / ${bottom}`} isInteractive />
  })
}

