// The pictures: Clawd, his token printer and the tokens it prints. SVG markup
// (SMIL-animated) for the surfaces that draw `Svg`, block-art rows for the
// terminal. Pure strings, so the same scene always yields the same markup.

import type { PrintLevel } from '../types'

export const ORANGE = '#D97757'
export const MUTED = '#8A8A93'
const INK = '#2B1D18'
const MONO = 'ui-monospace, SFMono-Regular, Menlo, monospace'
const IMPACT = "Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif"

/**
 * What the printer is up to: a print level while a turn runs; between turns
 * `idle` (it steams after a run, then Clawd dozes), `drowsy` (he dozes right
 * off) or `ready` (there is a draft in the prompt box: he startles awake).
 */
export type Scene = PrintLevel | 'idle' | 'drowsy' | 'ready'

/** How Clawd looks in a picture: blinking, gleeful, too cool (ultra), or nodding off. */
type Look = 'plain' | 'gleeful' | 'shades' | 'dozing'

/** How many steps Clawd's gaze takes across the prompt box. */
export const ACROSS = 6

/** Where the caret is, as Clawd sees it: the step across the box, and whether past its first line. */
export type Gaze = { across: number; isLower: boolean }

/** Seconds the printer steams after a run before Clawd dozes off. */
const COOLDOWN = 6


type Rect = readonly [x: number, y: number, width: number, height: number]

const rects = (color: string, list: readonly Rect[]) =>
  list.map(([x, y, w, h]) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${color}"/>`).join('')

const forever = (seconds: number, begin = 0) =>
  `dur="${seconds}s" begin="${begin.toFixed(2)}s" repeatCount="indefinite"`

const shaking = (amp: number, seconds: number) =>
  amp > 0
    ? `<animateTransform attributeName="transform" type="translate" values="0 0;${amp} ${-amp};${-amp} ${amp / 2};${amp / 2} ${amp};0 0" ${forever(seconds)}/>`
    : ''

/** Markup-safe and ASCII-only: anything else becomes a numeric entity. */
const escape = (text: string) => text.replace(/[&<>"']|[^\x20-\x7E]/gu, c => `&#${c.codePointAt(0)};`)

/** An Svg element's props: the markup, and the size to draw it at in CSS pixels. */
export type Picture = { source: string; width: number; height: number }

// The desktop draws an interactive Svg in a frame of its own: a default 300×150
// unless told the size, and light unless told otherwise, which a dark app shows
// as an opaque white backdrop. So every picture carries its size, and its frame
// follows the app's colour scheme. Any change to a picture (its markup or its
// size) makes the desktop reload its frame, restarting its animations.
const svg = (width: number, height: number, body: string, scale = 1): Picture => ({
  source: `<svg xmlns="http://www.w3.org/2000/svg" width="${width * scale}" height="${height * scale}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMinYMid meet"><style>:root{color-scheme:light dark}</style>${body}</svg>`,
  width: width * scale,
  height: height * scale,
})

export const grouped = (n: number) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')

export const compact = (n: number) =>
  n >= 1e6 ? `${+(n / 1e6).toFixed(1)}M` : n >= 1e3 ? `${+(n / 1e3).toFixed(1)}k` : String(n)

/** Clawd as the Claude Code logo draws him: 18×10 pixels of `px` each. */
function clawd(x: number, y: number, px: number, beat: number, look: Look, doze = COOLDOWN): string {
  const hop = beat > 0 ? `<animateTransform attributeName="transform" type="translate" values="0 0;0 -1;0 0" ${forever(beat)}/>` : ''
  const arm = (left: number, values: string) =>
    `<rect x="${left}" y="4" width="2" height="2" fill="${ORANGE}">${beat > 0 ? `<animate attributeName="y" values="${values}" ${forever(beat)}/>` : ''}</rect>`
  const blink = (top: number) => `<animate attributeName="height" values="2;2;0.3;2" keyTimes="0;0.92;0.96;1" ${forever(3.2)}/><animate attributeName="y" values="${top};${top};${top + 0.85};${top}" keyTimes="0;0.92;0.96;1" ${forever(3.2)}/>`
  const open = (top = 2) => `<rect x="5" y="${top}" width="1" height="2" fill="${INK}">${blink(top)}</rect><rect x="12" y="${top}" width="1" height="2" fill="${INK}">${blink(top)}</rect>`
  const at = (seconds: number, visibility: 'visible' | 'hidden') => `<set attributeName="visibility" to="${visibility}" begin="${seconds}s" fill="freeze"/>`
  const eyes = {
    plain: open(),
    gleeful: rects(INK, [[4, 3, 1, 1], [5, 2, 1, 1], [6, 3, 1, 1], [11, 3, 1, 1], [12, 2, 1, 1], [13, 3, 1, 1]]),
    // Lenses inside the face, so its orange frames them on a dark background too.
    shades: `<g class="shades">${rects('#111111', [[4, 2, 4, 2], [10, 2, 4, 2], [8, 2, 2, 1]])}<rect x="10" y="2" width="1" height="1" fill="#FFFFFF" opacity="0.45"/><rect x="4" y="2" width="1" height="1" fill="#FFFFFF" opacity="0.45"><animate attributeName="opacity" values="0.45;0.45;1;0.45" keyTimes="0;0.8;0.9;1" ${forever(2.5)}/></rect></g>`,
    dozing: `<g>${open()}${at(doze, 'hidden')}</g><g visibility="hidden">${rects(INK, [[4, 3, 2, 1], [12, 3, 2, 1]])}${at(doze, 'visible')}</g>`,
    // Wide-eyed for the beat, then eyes down on the prompt box.
  }[look]

  return `<g transform="translate(${x} ${y}) scale(${px})" shape-rendering="crispEdges"><g>${hop}${rects(ORANGE, [[3, 0, 12, 8], [4, 8, 1, 2], [6, 8, 1, 2], [11, 8, 1, 2]])}<rect x="13" y="8" width="1" height="2" fill="${ORANGE}"/>${arm(1, '4;2;4')}${arm(15, '2;4;2')}${eyes}</g></g>`
}

/** The token printer: 26×17 pixels of `px` each, its slot opening at (26, 8). */
function printer(x: number, y: number, px: number, level: PrintLevel, shake: number, isSteaming: boolean): string {
  const feed = level > 0
    ? `<animateTransform attributeName="transform" type="translate" values="0 0;0 1;0 0" ${forever(0.3)}/>`
    : ''
  const lights = [4, 6, 8].map((left, i) =>
    `<rect x="${left}" y="8" width="1" height="1" fill="#5FD38D"><animate attributeName="opacity" values="1;0.15;1" ${forever(level > 0 ? 0.45 : 1.6, -i * 0.15)}/></rect>`).join('')
  const led = level > 0
    ? `<rect x="20" y="11" width="2" height="1" fill="#5FD38D"><animate attributeName="opacity" values="1;0.2;1" ${forever(0.25)}/></rect>`
    : rects('#E5534B', [[20, 11, 2, 1]])
  const steam = isSteaming
    ? [7, 11.5, 16].map((cx, i) => {
      const puff = `dur="1.5s" begin="${i * 0.5}s" repeatCount="4"`
      return `<circle cx="${cx}" cy="1" r="1" fill="${MUTED}" opacity="0"><animate attributeName="cy" values="1;-2.5" ${puff}/><animate attributeName="r" values="0.8;1.8" ${puff}/><animate attributeName="opacity" values="0.9;0" ${puff}/></circle>`
    }).join('')
    : ''
  const whoosh = level >= 2
    ? `<g stroke="${MUTED}" stroke-width="0.6" stroke-linecap="round" fill="none"><path d="M-1.5 6l-2.5-1.5M-1.5 10h-3M-1.5 14l-2.5 1.5M4-1l-1.2-2.4M12-1v-2.6"/><animate attributeName="opacity" values="1;0.1;1" ${forever(0.2)}/></g>`
    : ''

  return `<g transform="translate(${x} ${y}) scale(${px})"><g>${shaking(shake / px, 0.12)}<g shape-rendering="crispEdges"><g>${feed}${rects('#F4EDE1', [[5, 0, 13, 4]])}${rects('#C9C1B3', [[7, 1, 8, 0.4], [7, 2.2, 6, 0.4]])}</g>${rects('#8B8B97', [[1, 3, 22, 3]])}${rects('#5B5B66', [[0, 5, 24, 9]])}${rects('#6E6E7A', [[0, 5, 24, 1]])}${rects('#143326', [[3, 7, 7, 3]])}${lights}${rects('#1E1E24', [[22, 7, 4, 2]])}${rects('#3A3A44', [[22, 9, 4, 1], [1, 14, 22, 2]])}${rects('#2A2A32', [[2, 16, 4, 1], [18, 16, 4, 1]])}${led}</g><path d="M16.5 7.4v4.2M14.4 9.5h4.2M15 8l3 3M18 8l-3 3" stroke="${ORANGE}" stroke-width="0.7" stroke-linecap="round"/></g>${whoosh}${steam}</g>`
}

/** One token: a bill with Claude's spark on it, `w` wide, centred on 0 0. */
function bill(w: number): string {
  const h = w * 0.56
  const r = h * 0.3
  const d = r * 0.7
  return `<rect x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" rx="${h * 0.12}" fill="#F7EEDC" stroke="#C96442" stroke-width="${w / 16}"/><path d="M0 ${-r}V${r}M${-r} 0H${r}M${-d} ${-d}L${d} ${d}M${d} ${-d}L${-d} ${d}" stroke="${ORANGE}" stroke-width="${w / 14}" stroke-linecap="round"/>`
}

/** `count` tokens flying out of a slot at x y, each flight `seconds` long; `lift` flattens the arcs. */
function tokens(x: number, y: number, count: number, seconds: number, reach: number, w: number, lift = 1): string {
  const flights = Array.from({ length: count }, (_, i) => {
    const rise = reach * (0.12 + ((i * 7) % 5) * 0.05) * lift
    const land = reach * (((i * 5) % 7) * 0.05 - 0.05) * lift
    const far = reach * (0.72 + ((i * 3) % 4) * 0.09)
    const path = `M0 0C${(far * 0.3).toFixed(1)} ${(-rise * 1.4).toFixed(1)} ${(far * 0.65).toFixed(1)} ${(-rise).toFixed(1)} ${far.toFixed(1)} ${land.toFixed(1)}`
    const begin = -(i / count) * seconds
    const tilt = (i * 47) % 360
    const turn = i % 2 === 0 ? 360 : -360
    const spin = 0.45 + ((i * 3) % 5) * 0.12
    return `<g opacity="0"><animateMotion path="${path}" ${forever(seconds, begin)}/><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;0.06;0.72;1" ${forever(seconds, begin)}/><g><animateTransform attributeName="transform" type="rotate" values="${tilt};${tilt + turn}" ${forever(spin)}/>${bill(w)}</g></g>`
  })
  return `<g transform="translate(${x} ${y})">${flights.join('')}</g>`
}

const TEMPO = [
  { count: 1, seconds: 2.6, shake: 0, beat: 0 },
  { count: 3, seconds: 1.8, shake: 0.3, beat: 0.6 },
  { count: 5, seconds: 1.3, shake: 0.5, beat: 0.45 },
  { count: 8, seconds: 0.95, shake: 0.8, beat: 0.3 },
] as const

/** Z's drifting up off Clawd once he has dozed off, `doze` seconds in. */
const zzz = (doze: number) => [0, 1, 2].map(i => {
  const drift = `dur="2.4s" begin="${doze + i * 0.8}s" repeatCount="indefinite"`
  return `<text x="${24 + i * 2.5}" y="7" font-family="${MONO}" font-size="${4 + i}" fill="${MUTED}" opacity="0">z<animate attributeName="y" values="7;1" ${drift}/><animate attributeName="opacity" values="0;1;0" ${drift}/></text>`
}).join('')

/**
 * Clawd at the printer as a picture (the Token Reserve draws it). Printing, it
 * runs at the level; idle, it steams for a few seconds and Clawd dozes off,
 * unless he wears shades.
 */
export function strip(scene: PrintLevel | 'idle', hasShades: boolean, scale = 1): Picture {
  if (scene === 'idle') {
    const doze = COOLDOWN
    return svg(136, 20,
      clawd(1, 5, 1.5, 0, hasShades ? 'shades' : 'dozing', doze)
      + printer(34, 3, 1, 0, 0, true)
      + (hasShades ? '' : zzz(doze)), scale)
  }

  const tempo = TEMPO[scene]
  return svg(136, 20,
    clawd(1, 5, 1.5, tempo.beat, hasShades ? 'shades' : scene === 3 ? 'gleeful' : 'plain')
    + printer(34, 3, 1, scene, tempo.shake, false)
    + tokens(62, 11, tempo.count, tempo.seconds, 70, 8, 0.25), scale)
}

/** Tokens per reply as bars, newest on the right; hovering one names its count. */
export function chart(runs: readonly number[]): Picture {
  const width = 280
  const base = 62
  const gap = 2
  const most = Math.max(1, ...runs)
  const barWidth = Math.min(24, (width - gap * (runs.length - 1)) / runs.length)
  const columns = runs.map((run, i) => {
    const x = width - (runs.length - i) * (barWidth + gap) + gap
    const h = Math.max(2, (run / most) * (base - 14))
    const r = Math.min(4, barWidth / 2, h)
    const y = base - h
    const ago = runs.length - 1 - i
    return `<g class="col"><title>${ago === 0 ? 'Last reply' : `${ago + 1} replies ago`}: ${grouped(run)} tokens</title><rect x="${x - gap / 2}" y="0" width="${barWidth + gap}" height="${base}" fill="transparent"/><path class="bar" d="M${x} ${base}V${y + r}Q${x} ${y} ${x + r} ${y}H${x + barWidth - r}Q${x + barWidth} ${y} ${x + barWidth} ${y + r}V${base}Z"/></g>`
  }).join('')
  return svg(width, 64,
    '<style>.bar{fill:#D97757}.col:hover .bar{fill-opacity:.7}.ink{fill:#6B6A66}.rule{stroke:#8A8A93;stroke-opacity:.5}'
    + '@media (prefers-color-scheme:dark){.bar{fill:#D06A48}.ink{fill:#A3A29E}}</style>'
    + `<text class="ink" x="0" y="8" font-family="${MONO}" font-size="9">max ${grouped(most)}</text>`
    + columns
    + `<line class="rule" x1="0" y1="${base + 0.5}" x2="${width}" y2="${base + 0.5}"/>`)
}

const FACE = [
  '.....HHHHHH.....',
  '...HHHHHHHHHH...',
  '..HHHHHHHHHHHH..',
  '..HSSSSSSSSSSH..',
  '.HSSSbSSSSbSSSH.',
  '.HSbbSSSSSSbbSH.',
  '.SSEEESSSSEEESS.',
  '.STTSSSSSSSSTTS.',
  '.STTSSSSSSSSTTS.',
  '.STSSSMMMMSSSTS.',
  '.STSSMMttMMSSTS.',
  '..TSSMMMMMMSST..',
  '..TSSSSSSSSSST..',
  '...SSSSSSSSSS...',
  '....SSSSSSSS....',
] as const

const FACE_COLORS: Readonly<Record<string, string>> = {
  H: '#3B2A20', b: '#3B2A20', E: '#3B2A20', S: '#F2C7A5', T: '#5DADE2', M: '#5A1E1E', t: '#D9534F',
}

/** A pixel map as runs of rects, one colour per letter, `.` left empty. */
function pixels(map: readonly string[], colors: Readonly<Record<string, string>>): string {
  return map.map((row, y) => {
    const runs: string[] = []
    for (let x = 0; x < row.length;) {
      const c = row.charAt(x)
      let run = 1
      while (row.charAt(x + run) === c) run += 1
      const color = colors[c]
      if (color !== undefined) runs.push(`<rect x="${x}" y="${y}" width="${run}" height="1" fill="${color}"/>`)
      x += run
    }
    return runs.join('')
  }).join('')
}

/** The one begging the printer to stop: sobbing, 16×15 pixels of `px` each. */
function crier(x: number, y: number, px: number): string {
  const drops = ([[2.5, 0], [13.5, 0.45]] as const).map(([cx, lag]) =>
    `<rect x="${cx - 0.5}" y="13" width="1" height="1" fill="#5DADE2"><animate attributeName="y" values="13;17" ${forever(0.9, -lag)}/><animate attributeName="opacity" values="1;0" ${forever(0.9, -lag)}/></rect>`).join('')
  return `<g transform="translate(${x} ${y}) scale(${px})" shape-rendering="crispEdges"><g><animateTransform attributeName="transform" type="translate" values="0 0;0.25 0;-0.25 0;0 0" ${forever(0.3)}/>${pixels(FACE, FACE_COLORS)}${drops}</g></g>`
}

function wrap(text: string, max: number): string[] {
  const lines: string[] = []
  let line = ''
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (line !== '' && line.length + 1 + word.length > max) {
      lines.push(line)
      line = word
    } else {
      line = line === '' ? word : `${line} ${word}`
    }
  }
  return line === '' ? lines : [...lines, line]
}

/** Meme text: white Impact with a black outline, wrapped, centred on cx. */
function caption(text: string, cx: number, y: number): string {
  const lines = wrap(text.toUpperCase(), 32)
  const shown = lines.length > 3 ? [...lines.slice(0, 2), `${lines[2]}…`] : lines
  const size = shown.length > 2 ? 24 : 30
  const spans = shown.map((line, i) => `<tspan x="${cx}" dy="${i === 0 ? 0 : size * 1.1}">${escape(line)}</tspan>`).join('')
  return `<text x="${cx}" y="${y}" text-anchor="middle" font-family="${IMPACT}" font-size="${size}" fill="#FFFFFF" stroke="#000000" stroke-width="${size / 5}" stroke-linejoin="round" paint-order="stroke">${spans}</text>`
}

/** The meme: someone begging the printer to stop, then Clawd printing anyway. */
export function meme(top: string, bottom: string, stats: string, hasShades = false): Picture {
  return svg(500, 484,
    `<rect x="1.5" y="1.5" width="497" height="235" fill="#FFFFFF" stroke="#111111" stroke-width="3"/>`
    + crier(194, 112, 7)
    + caption(top, 250, 42)
    + `<rect x="1.5" y="242.5" width="497" height="240" fill="#FFF4E8" stroke="#111111" stroke-width="3"/>`
    + clawd(26, 386, 5, 0.3, hasShades ? 'shades' : 'gleeful')
    + printer(126, 351, 5, 3, 2, false)
    + tokens(258, 391, 12, 1.05, 220, 24)
    + caption(bottom, 250, 286)
    + `<text x="250" y="470" text-anchor="middle" font-family="${MONO}" font-size="12" fill="#7A6A60">${escape(stats)}</text>`)
}

/** The meme's bottom panel for the terminal: rows of [text, colour] runs. */
export const BLOCK_ART: readonly (readonly (readonly [string, string])[])[] = [
  [[' ▐▛███▜▌ ', ORANGE], ['  ┌──────┐', MUTED], ['    ✻     ✻', ORANGE]],
  [['▝▜█████▛▘', ORANGE], ['  │ ▒▒ ✻ ├═', MUTED], ['  ✻   ✻     ✻', ORANGE]],
  [['  ▘▘ ▝▝  ', ORANGE], ['  └──────┘', MUTED], ['  ✻    ✻   ✻', ORANGE]],
]

/** Tokens per reply as one row of block heights, for the terminal. */
export function sparkline(runs: readonly number[]): string {
  const most = Math.max(1, ...runs)
  return runs.map(run => '▁▂▃▄▅▆▇█'.charAt(Math.min(7, Math.floor((run / most) * 8)))).join('')
}

// The band drawn without pictures: a framebuffer of 100 by 20 pixels that the
// band lays out as boxes (each pixel 1% wide and 5% tall), so a new moment
// changes boxes in place and nothing reloads. `frame` paints one moment.

/** How long a tick of the band's clock lasts; animation is counted in ticks. */
export const TICK_MS = 125

/** What each letter of a frame paints; `.` paints nothing. */
export const PALETTE: Readonly<Record<string, string>> = {
  O: ORANGE, E: INK, K: '#111111', W: '#FFFFFF', M: MUTED,
  P: '#F4EDE1', L: '#C9C1B3', T: '#8B8B97', B: '#5B5B66', D: '#143326', G: '#5FD38D', g: '#2E6B4A',
  Y: ORANGE, S: '#1E1E24', X: '#3A3A44', F: '#2A2A32', R: '#E5534B', A: '#F2C14E',
  C: '#F7EEDC', c: '#C96442',
}

/** One moment of the band: its scene, ticks into it, and how Clawd looks. */
export type Moment = { scene: Scene; t: number; hasShades: boolean; gaze: Gaze }

const WIDE = 100
const TALL = 20
/** Ticks the printer steams after a run; ticks Clawd takes to doze with nothing printed. */
const COOL_TICKS = 48
const DROWSE_TICKS = 10
/** Ticks Clawd stays startled when a draft appears; he blinks every BLINK_TICKS. */
const STARTLE_TICKS = 8
const BLINK_TICKS = 28

/** How the printer runs per level: tokens in the air, ticks per flight, Clawd's beat, the shake's. */
const PRESS = [
  { bills: 1, flight: 24, beat: 0, shake: 0 },
  { bills: 2, flight: 16, beat: 4, shake: 0 },
  { bills: 3, flight: 12, beat: 3, shake: 2 },
  { bills: 5, flight: 9, beat: 2, shake: 1 },
] as const

/** Clawd's body as the logo draws it; his arms, legs and eyes go on top. */
const CLAWD_BODY = Array.from({ length: 8 }, () => '...OOOOOOOOOOOO...')

const PRINTER = [
  '....PPPPPPPPP....',
  '....PLLLLLLPP....',
  '.TTTTTTTTTTTTTTT.',
  'BBBBBBBBBBBBBBBSS',
  'BDDDDDBBBBBBBBBSS',
  'BDgDgDBBBBYBBBB..',
  'BDDDDDBBBYYYBBB..',
  'BBBBBBBBBBYBBBB..',
  'BBBBBBBBBBBBBBB..',
  '.XXXXXXXXXXXXX...',
  '.FF.........FF...',
] as const

const BILL_FLAT = ['cccc', 'cCCc', 'cccc'] as const
const BILL_UP = ['ccc', 'cCc', 'cCc', 'ccc'] as const
const ZED = ['MMM', '..M', '.M.', 'MMM'] as const
const BANG = ['AA', 'AA', 'AA', 'AA', 'AA', '..', 'AA'] as const
/** Max effort's shades: over his eyes while printing, pushed up on his head otherwise. */
const SHADES = ['KKKKKKKKKK', 'KKKK..KKKK'] as const

/** Clawd's eyes, one step per sixth of the prompt box: how far across they look. */
const GAZE_DX = [-1, 0, 0, 1, 1, 2] as const

type Grid = string[][]
type Eyes = 'open' | 'gleeful' | 'shades' | 'closed' | 'wide' | 'watch'

function stamp(grid: Grid, sprite: readonly string[], x: number, y: number) {
  sprite.forEach((row, dy) => {
    const line = grid[y + dy]
    for (let dx = 0; dx < row.length; dx += 1) {
      const letter = row.charAt(dx)
      if (letter !== '.' && line !== undefined && x + dx >= 0 && x + dx < WIDE) line[x + dx] = letter
    }
  })
}

const plot = (grid: Grid, cells: readonly (readonly [number, number])[], x: number, y: number, letter: string) =>
  cells.forEach(([cx, cy]) => stamp(grid, [letter], x + cx, y + cy))

function drawClawd(grid: Grid, x: number, y: number, eyes: Eyes, { arms = 'down', isTapping = false, isBlinking = false, gaze = { across: 0, isLower: false } }: {
  arms?: 'down' | 'up' | 'left' | 'right'; isTapping?: boolean; isBlinking?: boolean; gaze?: Gaze
} = {}) {
  stamp(grid, CLAWD_BODY, x, y)
  stamp(grid, ['OO', 'OO'], x + 1, y + (arms === 'up' || arms === 'left' ? 2 : 4))
  stamp(grid, ['OO', 'OO'], x + 15, y + (arms === 'up' || arms === 'right' ? 2 : 4))
  for (const leg of [4, 6, 11]) stamp(grid, ['O', 'O'], x + leg, y + 8)
  stamp(grid, isTapping ? ['O'] : ['O', 'O'], x + 13, y + 8)

  if (eyes === 'shades') {
    stamp(grid, SHADES, x + 4, y + 2)
    plot(grid, [[4, 2]], x, y, 'W')
    return
  }

  const dx = eyes === 'watch' ? GAZE_DX[gaze.across] ?? 0 : 0
  const top = eyes === 'watch' ? 3 + (gaze.isLower ? 1 : 0) : 2
  const cells: Record<Exclude<Eyes, 'shades'>, readonly (readonly [number, number])[]> = {
    open: [[5, top], [5, top + 1], [12, top], [12, top + 1]],
    watch: [[5 + dx, top], [5 + dx, top + 1], [12 + dx, top], [12 + dx, top + 1]],
    gleeful: [[4, 3], [5, 2], [6, 3], [11, 3], [12, 2], [13, 3]],
    closed: [[4, 3], [5, 3], [12, 3], [13, 3]],
    wide: [[4, 1], [5, 1], [4, 2], [5, 2], [4, 3], [5, 3], [12, 1], [13, 1], [12, 2], [13, 2], [12, 3], [13, 3]],
  }
  // A blink closes open eyes to their lower pixel.
  plot(grid, isBlinking && (eyes === 'open' || eyes === 'watch') ? cells[eyes].filter((_, i) => i % 2 === 1) : cells[eyes], x, y, 'E')
}

function drawPrinter(grid: Grid, x: number, y: number, led: string, lit: number) {
  stamp(grid, PRINTER, x, y)
  plot(grid, [[13, 7]], x, y, led)
  if (lit & 1) plot(grid, [[2, 5]], x, y, 'G')
  if (lit & 2) plot(grid, [[4, 5]], x, y, 'G')
}

function drawBills(grid: Grid, count: number, flight: number, t: number) {
  for (let i = 0; i < count; i += 1) {
    const u = ((t + (i * flight) / count) % flight) / flight
    if (u > 0.92) continue
    const reach = 38 + ((i * 7) % 15)
    const rise = 4 + ((i * 3) % 5)
    const drop = ((i * 5) % 6) - 1
    const bill = (Math.floor(t / 2) + i) % 2 === 0 ? BILL_FLAT : BILL_UP
    stamp(grid, bill, 41 + Math.round(u * reach), Math.round(11 - rise * Math.sin(Math.PI * u) + drop * u))
  }
}

/** One moment of the band as rows of palette letters, 100 across and 20 down. */
export function frame({ scene, t, hasShades, gaze }: Moment): string[] {
  const grid: Grid = Array.from({ length: TALL }, () => Array.from({ length: WIDE }, () => '.'))
  const isBlinking = t % BLINK_TICKS >= BLINK_TICKS - 2

  if (typeof scene === 'number') {
    const press = PRESS[scene]
    const beat = press.beat > 0 ? Math.floor(t / press.beat) % 2 : 0
    drawClawd(grid, 1, 10 - beat, hasShades ? 'shades' : scene === 3 ? 'gleeful' : 'open', {
      arms: press.beat > 0 ? (beat === 1 ? 'left' : 'right') : 'down',
      isBlinking,
    })
    const shake = press.shake > 0 ? Math.floor(t / press.shake) % 2 : 0
    drawPrinter(grid, 23 + shake, 9, t % 2 === 0 ? 'G' : 'X', 1 << (t % 2))
    if (scene >= 2 && t % 2 === 0) plot(grid, [[-2, 2], [-3, 5], [-2, 8]], 23, 9, 'M')
    drawBills(grid, press.bills, press.flight, t)
  } else if (scene === 'ready') {
    // A draft startles him (a jump, arms up, a "!"), then he watches the caret,
    // any shades pushed up so his eyes show.
    const isStartled = t < STARTLE_TICKS
    const y = isStartled ? Math.min(10, 8 + Math.floor(t / 2)) : 10
    drawClawd(grid, 1, y, isStartled ? 'wide' : 'watch',
      { arms: isStartled ? 'up' : 'down', isTapping: !isStartled && t % 8 < 2, isBlinking, gaze })
    if (hasShades) stamp(grid, SHADES, 5, y - 1)
    drawPrinter(grid, 23, 9, Math.floor(t / 4) % 2 === 0 ? 'A' : 'X', 3)
    if (t < STARTLE_TICKS + 2) stamp(grid, BANG, 20, 2)
  } else {
    // After a run the printer steams, then Clawd dozes off, any shades pushed up.
    const doze = scene === 'idle' ? COOL_TICKS : DROWSE_TICKS
    const isAsleep = t >= doze
    drawClawd(grid, 1, 10, isAsleep ? 'closed' : 'open', { isBlinking })
    if (hasShades) stamp(grid, SHADES, 5, 9)
    drawPrinter(grid, 23, 9, 'R', 0)
    if (scene === 'idle' && t < COOL_TICKS) {
      ;[6, 9, 12].forEach((col, k) => plot(grid, [[col, -1 - ((Math.floor(t / 2) + k * 2) % 5)]], 23, 9, 'M'))
    }
    if (isAsleep) {
      const rise = Math.floor(t / 3) % 6
      stamp(grid, ZED, 19 + (rise > 2 ? 1 : 0), 7 - rise)
    }
  }

  return grid.map(row => row.join(''))
}

/** Ticks between redraws of a scene, `t` ticks in: only as often as something moves. */
export function cadence(scene: Scene, t: number): number {
  if (typeof scene === 'number') return 1
  if (scene === 'ready') return t < STARTLE_TICKS + 2 ? 1 : 2
  return scene === 'idle' && t < COOL_TICKS ? 2 : 3
}

/** Whether the ready scene still says its intro ("Ooh, a prompt!"), `t` ticks in. */
export const isIntro = (t: number) => t < STARTLE_TICKS + 2

/** Ticks into the ready scene where the startle is over: where it starts if he was awake. */
export const SETTLED_TICKS = STARTLE_TICKS + 2

/** Whether Clawd has dozed off, `t` ticks into a scene (only idle and drowsy ones doze). */
export const isAsleep = (scene: Scene, t: number) =>
  scene === 'idle' ? t >= COOL_TICKS : scene === 'drowsy' && t >= DROWSE_TICKS

